231	// convertUserSettingToStore converts API UserSetting to store UserSetting.
232	func convertUserSettingToStore(apiSetting *v1pb.UserSetting, userID int32, key storepb.UserSetting_Key) (*storepb.UserSetting, error) {
233		storeSetting := &storepb.UserSetting{
234			UserId: userID,
235			Key:    key,
236		}
237	
238		switch key {
239		case storepb.UserSetting_GENERAL:
240			if general := apiSetting.GetGeneralSetting(); general != nil {
241				storeSetting.Value = &storepb.UserSetting_General{
242					General: &storepb.GeneralUserSetting{
243						Locale:         general.Locale,
244						MemoVisibility: general.MemoVisibility,
245						Theme:          general.Theme,
246					},
247				}
248			} else {
249				return nil, errors.Errorf("general setting is required")
250			}
251		case storepb.UserSetting_WEBHOOKS:
252			if webhooks := apiSetting.GetWebhooksSetting(); webhooks != nil {
253				storeWebhooks := make([]*storepb.WebhooksUserSetting_Webhook, 0, len(webhooks.Webhooks))
254				for _, webhook := range webhooks.Webhooks {
255					storeWebhook := &storepb.WebhooksUserSetting_Webhook{
256						Id:    extractWebhookIDFromName(webhook.Name),
257						Title: webhook.DisplayName,
258						Url:   webhook.Url,
259					}
260					storeWebhooks = append(storeWebhooks, storeWebhook)
261				}
262				storeSetting.Value = &storepb.UserSetting_Webhooks{
263					Webhooks: &storepb.WebhooksUserSetting{
264						Webhooks: storeWebhooks,
265					},
266				}
267			} else {
268				return nil, errors.Errorf("webhooks setting is required")
269			}
270		case storepb.UserSetting_TAGS:
271			if tags := apiSetting.GetTagsSetting(); tags != nil {
272				storeSetting.Value = &storepb.UserSetting_Tags{
273					Tags: convertUserTagsSettingToStore(tags),
274				}
275			} else {
276				return nil, errors.Errorf("tags setting is required")
277			}
278		default:
279			return nil, errors.Errorf("unsupported setting key: %v", key)
280		}
281	
282		return storeSetting, nil
283	}
284	
285	// extractWebhookIDFromName extracts webhook ID from resource name.
286	// e.g., "users/123/webhooks/webhook-id" -> "webhook-id".
